contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 mintedAmount, uint256 burnedAmount) public {
        require(burnedAmount <= c.balanceOf(address(this)), "burn amount must not exceed balance");

        uint256 initialSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 initialBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        c.mintToken(address(this), mintedAmount); if (__ESBMC_reverted()) return;
        c.burn(burnedAmount); if (__ESBMC_reverted()) return;

        uint256 finalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 finalBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        assert(finalSupply - initialSupply + burnedAmount == mintedAmount && finalBalance - initialBalance + burnedAmount == mintedAmount);
    }
}

